/** Domain error raised when a business invariant is violated. */
export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DomainError';
  }
}

/** Immutable Value Object representing a monetary amount in a single currency. */
export class Money {
  public readonly amount: number;
  public readonly currency: string;

  constructor(amount: number, currency: string) {
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new DomainError('Money amount must be a finite number');
    }
    if (amount < 0) throw new DomainError('Money amount cannot be negative');
    if (typeof currency !== 'string' || !/^[A-Za-z]{3}$/.test(currency)) {
      throw new DomainError('Currency must be a 3-letter ISO code');
    }
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase();
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  static zero(currency: string): Money {
    return new Money(0, currency);
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amount + other.amount, this.currency);
  }

  subtract(other: Money): Money {
    this.assertSameCurrency(other);
    if (other.amount > this.amount) throw new DomainError('Result would be negative');
    return new Money(this.amount - other.amount, this.currency);
  }

  multiply(factor: number): Money {
    if (typeof factor !== 'number' || !Number.isFinite(factor) || factor < 0) {
      throw new DomainError('Factor must be a non-negative finite number');
    }
    return new Money(this.amount * factor, this.currency);
  }

  equals(other: Money): boolean {
    return !!other && this.amount === other.amount && this.currency === other.currency;
  }

  isZero(): boolean {
    return this.amount === 0;
  }

  toString(): string {
    return `${this.amount.toFixed(2)} ${this.currency}`;
  }

  private assertSameCurrency(other: Money): void {
    if (!(other instanceof Money)) throw new DomainError('Expected a Money instance');
    if (other.currency !== this.currency) {
      throw new DomainError(`Currency mismatch: ${this.currency} vs ${other.currency}`);
    }
  }
}

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export interface OrderItemSnapshot {
  itemId: string;
  quantity: number;
  unitPrice: Money;
  lineTotal: Money;
}

export interface DomainEvent {
  type: string;
  aggregateId: string;
  occurredAt: Date;
  payload: Record<string, unknown>;
}

const TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['SHIPPED', 'CANCELLED'],
  SHIPPED: [],
  CANCELLED: [],
};

/** Order aggregate root: enforces item, currency and lifecycle invariants. */
export class Order {
  public readonly id: string;
  public readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private readonly _items = new Map<string, { quantity: number; unitPrice: Money }>();
  private readonly _events: DomainEvent[] = [];
  private _version = 0;

  constructor(id: string, customerId: string) {
    if (!id || typeof id !== 'string') throw new DomainError('Order id is required');
    if (!customerId || typeof customerId !== 'string') throw new DomainError('customerId is required');
    this.id = id;
    this.customerId = customerId;
    this.record('OrderCreated', { customerId });
  }

  get status(): OrderStatus {
    return this._status;
  }

  get version(): number {
    return this._version;
  }

  get items(): OrderItemSnapshot[] {
    return [...this._items.entries()].map(([itemId, l]) => ({
      itemId,
      quantity: l.quantity,
      unitPrice: l.unitPrice,
      lineTotal: l.unitPrice.multiply(l.quantity),
    }));
  }

  addItem(itemId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new DomainError(`Cannot modify items of an order in status ${this._status}`);
    }
    if (!itemId || typeof itemId !== 'string') throw new DomainError('itemId is required');
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError('quantity must be a positive integer');
    }
    if (!(price instanceof Money)) throw new DomainError('price must be a Money instance');
    if (price.isZero()) throw new DomainError('price must be greater than zero');

    const currency = this.currency();
    if (currency && currency !== price.currency) {
      throw new DomainError(`Order currency is ${currency}, cannot add ${price.currency}`);
    }

    const existing = this._items.get(itemId);
    if (existing) {
      if (!existing.unitPrice.equals(price)) {
        throw new DomainError(`Conflicting price for item ${itemId}`);
      }
      existing.quantity += quantity;
    } else {
      this._items.set(itemId, { quantity, unitPrice: price });
    }
    this.record('OrderItemAdded', { itemId, quantity, unitPrice: price.amount, currency: price.currency });
  }

  removeItem(itemId: string): void {
    if (this._status !== 'PENDING') {
      throw new DomainError(`Cannot modify items of an order in status ${this._status}`);
    }
    if (!this._items.delete(itemId)) throw new DomainError(`Item ${itemId} not found`);
    this.record('OrderItemRemoved', { itemId });
  }

  total(): Money {
    const currency = this.currency() ?? 'USD';
    return this.items.reduce((sum, i) => sum.add(i.lineTotal), Money.zero(currency));
  }

  pay(): void {
    if (this._items.size === 0) throw new DomainError('Cannot pay an order with no items');
    this.transition('PAID');
    const total = this.total();
    this.record('OrderPaid', { amount: total.amount, currency: total.currency });
  }

  ship(): void {
    this.transition('SHIPPED');
    this.record('OrderShipped', { itemCount: this._items.size });
  }

  cancel(): void {
    this.transition('CANCELLED');
    this.record('OrderCancelled', {});
  }

  getDomainEvents(): DomainEvent[] {
    return [...this._events];
  }

  pullDomainEvents(): DomainEvent[] {
    const events = [...this._events];
    this._events.length = 0;
    return events;
  }

  private currency(): string | null {
    const first = this._items.values().next();
    return first.done ? null : first.value.unitPrice.currency;
  }

  private transition(next: OrderStatus): void {
    if (!TRANSITIONS[this._status].includes(next)) {
      throw new DomainError(`Invalid transition ${this._status} -> ${next}`);
    }
    this._status = next;
  }

  private record(type: string, payload: Record<string, unknown>): void {
    this._version += 1;
    this._events.push({ type, aggregateId: this.id, occurredAt: new Date(), payload });
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

/** In-memory repository implementation suitable for tests and local runtime. */
export class InMemoryOrderRepository implements IOrderRepository {
  private readonly store = new Map<string, Order>();
  public readonly publishedEvents: DomainEvent[] = [];

  async findById(id: string): Promise<Order | null> {
    return this.store.get(id) ?? null;
  }

  async save(order: Order): Promise<void> {
    if (!(order instanceof Order)) throw new DomainError('save expects an Order aggregate');
    this.store.set(order.id, order);
    this.publishedEvents.push(...order.pullDomainEvents());
  }

  async findByCustomer(customerId: string): Promise<Order[]> {
    return [...this.store.values()].filter((o) => o.customerId === customerId);
  }

  async delete(id: string): Promise<boolean> {
    return this.store.delete(id);
  }

  clear(): void {
    this.store.clear();
    this.publishedEvents.length = 0;
  }
}

