/**
 * Order Bounded Context — Aggregate Root, Value Objects, Domain Events, Repository.
 * Self-contained DDD module: no framework/infrastructure leakage into the domain.
 */

/* ---------------------------------- Errors --------------------------------- */

export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

export class InvalidMoneyError extends DomainError {}
export class CurrencyMismatchError extends DomainError {}
export class InvalidQuantityError extends DomainError {}
export class InvalidIdentifierError extends DomainError {}
export class EmptyOrderError extends DomainError {}
export class InvalidStateTransitionError extends DomainError {
  constructor(from: OrderStatus, to: OrderStatus) {
    super(`Cannot transition order from ${from} to ${to}`);
  }
}
export class OrderNotFoundError extends DomainError {}

/* ------------------------------ Value Objects ------------------------------ */

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

/** Immutable monetary value stored in minor units to avoid float drift. */
export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) throw new InvalidMoneyError(`Amount must be finite: ${amount}`);
    if (amount < 0) throw new InvalidMoneyError(`Amount must be >= 0: ${amount}`);
    if (Math.round(amount * 100) !== Number((amount * 100).toFixed(0)))
      throw new InvalidMoneyError(`Amount exceeds 2 decimal places: ${amount}`);
    const normalized = (currency ?? '').trim().toUpperCase();
    if (!CURRENCY_PATTERN.test(normalized))
      throw new InvalidMoneyError(`Currency must be an ISO-4217 code: ${currency}`);
    this.amount = Math.round(amount * 100) / 100;
    this.currency = normalized;
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  static zero(currency: string): Money {
    return new Money(0, currency);
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.round(this.amount + other.amount), this.currency);
  }

  multiply(factor: number): Money {
    if (!Number.isInteger(factor) || factor < 0)
      throw new InvalidMoneyError(`Factor must be a non-negative integer: ${factor}`);
    return new Money(this.round(this.amount * factor), this.currency);
  }

  equals(other: Money): boolean {
    return other instanceof Money && this.amount === other.amount && this.currency === other.currency;
  }

  toString(): string {
    return `${this.amount.toFixed(2)} ${this.currency}`;
  }

  private assertSameCurrency(other: Money): void {
    if (!(other instanceof Money)) throw new InvalidMoneyError('Operand must be a Money instance');
    if (other.currency !== this.currency)
      throw new CurrencyMismatchError(`Currency mismatch: ${this.currency} vs ${other.currency}`);
  }

  private round(value: number): number {
    return Math.round(value * 100) / 100;
  }
}

/** Line item inside the Order aggregate — reachable only through the root. */
export class OrderItem {
  constructor(readonly itemId: string, readonly quantity: number, readonly unitPrice: Money) {
    Object.freeze(this);
  }

  get subtotal(): Money {
    return this.unitPrice.multiply(this.quantity);
  }

  withQuantity(quantity: number): OrderItem {
    return new OrderItem(this.itemId, quantity, this.unitPrice);
  }
}

/* ------------------------------ Domain Events ------------------------------ */

export interface DomainEvent {
  readonly name: string;
  readonly aggregateId: string;
  readonly occurredAt: Date;
}

export class OrderItemAdded implements DomainEvent {
  readonly name = 'order.item_added';
  readonly occurredAt = new Date();
  constructor(
    readonly aggregateId: string,
    readonly itemId: string,
    readonly quantity: number,
    readonly subtotal: Money,
  ) {}
}

export class OrderPaid implements DomainEvent {
  readonly name = 'order.paid';
  readonly occurredAt = new Date();
  constructor(readonly aggregateId: string, readonly customerId: string, readonly total: Money) {}
}

export class OrderShipped implements DomainEvent {
  readonly name = 'order.shipped';
  readonly occurredAt = new Date();
  constructor(readonly aggregateId: string, readonly customerId: string) {}
}

export class OrderCancelled implements DomainEvent {
  readonly name = 'order.cancelled';
  readonly occurredAt = new Date();
  constructor(readonly aggregateId: string, readonly previousStatus: OrderStatus) {}
}

/* -------------------------------- Aggregate -------------------------------- */

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

const TRANSITIONS: Readonly<Record<OrderStatus, readonly OrderStatus[]>> = Object.freeze({
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['SHIPPED', 'CANCELLED'],
  SHIPPED: [],
  CANCELLED: [],
});

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private readonly items = new Map<string, OrderItem>();
  private readonly events: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    this.id = Order.requireId(id, 'Order id');
    this.customerId = Order.requireId(customerId, 'Customer id');
  }

  get status(): OrderStatus {
    return this._status;
  }

  get lines(): readonly OrderItem[] {
    return Object.freeze([...this.items.values()]);
  }

  /** Sum of all line subtotals; zero-item orders have no currency, so total is null. */
  get total(): Money | null {
    const lines = [...this.items.values()];
    if (lines.length === 0) return null;
    return lines.slice(1).reduce((sum, line) => sum.add(line.subtotal), lines[0].subtotal);
  }

  addItem(itemId: string, quantity: number, price: Money): void {
    this.assertMutable('addItem');
    const key = Order.requireId(itemId, 'Item id');
    if (!Number.isInteger(quantity) || quantity <= 0)
      throw new InvalidQuantityError(`Quantity must be a positive integer: ${quantity}`);
    if (!(price instanceof Money)) throw new InvalidMoneyError('Price must be a Money instance');
    const existingCurrency = this.total?.currency;
    if (existingCurrency && existingCurrency !== price.currency)
      throw new CurrencyMismatchError(`Order is in ${existingCurrency}, got ${price.currency}`);

    const existing = this.items.get(key);
    if (existing && !existing.unitPrice.equals(price))
      throw new InvalidMoneyError(`Item ${key} already priced at ${existing.unitPrice.toString()}`);
    const line = existing ? existing.withQuantity(existing.quantity + quantity) : new OrderItem(key, quantity, price);
    this.items.set(key, line);
    this.events.push(new OrderItemAdded(this.id, key, line.quantity, line.subtotal));
  }

  pay(): void {
    this.transition('PAID');
    const total = this.total;
    if (!total) throw new EmptyOrderError(`Order ${this.id} has no items to pay for`);
    this._status = 'PAID';
    this.events.push(new OrderPaid(this.id, this.customerId, total));
  }

  ship(): void {
    this.transition('SHIPPED');
    this._status = 'SHIPPED';
    this.events.push(new OrderShipped(this.id, this.customerId));
  }

  cancel(): void {
    this.transition('CANCELLED');
    const previous = this._status;
    this._status = 'CANCELLED';
    this.events.push(new OrderCancelled(this.id, previous));
  }

  /** Drains recorded events so callers publish each event exactly once. */
  getDomainEvents(): DomainEvent[] {
    return this.events.splice(0, this.events.length);
  }

  private transition(to: OrderStatus): void {
    if (!TRANSITIONS[this._status].includes(to)) throw new InvalidStateTransitionError(this._status, to);
  }

  private assertMutable(operation: string): void {
    if (this._status !== 'PENDING')
      throw new InvalidStateTransitionError(this._status, 'PENDING');
    void operation;
  }

  private static requireId(value: string, label: string): string {
    if (typeof value !== 'string' || value.trim().length === 0)
      throw new InvalidIdentifierError(`${label} must be a non-empty string`);
    return value.trim();
  }
}

/* -------------------------------- Repository ------------------------------- */

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

/** In-memory repository for the Order aggregate: one repository per aggregate root. */
export class InMemoryOrderRepository implements IOrderRepository {
  private readonly store = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    return this.store.get(String(id ?? '').trim()) ?? null;
  }

  async save(order: Order): Promise<void> {
    if (!(order instanceof Order)) throw new DomainError('save() expects an Order aggregate');
    this.store.set(order.id, order);
  }

  async delete(id: string): Promise<void> {
    const key = String(id ?? '').trim();
    if (!this.store.delete(key)) throw new OrderNotFoundError(`Order ${key} not found`);
  }
}
